			if (cursor.type.isError) throw syntax;
			const { name, from, to } = cursor;
			if (!typescript && typescriptNodes.test(name)) throw syntax;
			if (!typescript && name === "PostfixExpression" && directName(cursor.node, "LogicOp", source) === "!") throw syntax;
